        flex: 1;
        padding: 9px 12px;
        border: 1px solid var(--border);
        border-radius: 7px;
        font-size: 13.5px;
        color: var(--text);
        background: #fff;
      }
      input:focus { outline: 2px solid rgba(37, 99, 235, 0.25); border-color: var(--accent); }
      button {
        background: var(--accent);
        color: #fff;
        border: 0;
        border-radius: 7px;
        padding: 9px 16px;
        font-size: 13.5px;
        font-weight: 600;
